import{_ as s,o as e,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const r=JSON.parse('{"title":"57. 静态和共享库","description":"The Little Book of C 中文版 — 57. 静态和共享库","frontmatter":{"title":"57. 静态和共享库","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","06-编译与构建","中文"],"description":"The Little Book of C 中文版 — 57. 静态和共享库","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":57,"sidebarWeight":57,"alternateZh":"/posts/c教程/zh-CN/06-编译与构建/057-Static and Shared Libraries","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/057-Static and Shared Libraries"},"headers":[],"relativePath":"posts/c教程/zh-CN/06-编译与构建/057-Static and Shared Libraries.md","filePath":"posts/c教程/zh-CN/06-编译与构建/057-Static and Shared Libraries.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/06-编译与构建/057-Static and Shared Libraries.md"};function i(l,a,o,c,d,h){return e(),n("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/06-Compilation and Build/057-Static and Shared Libraries)</p><p>在大型 C 项目中，您通常希望在多个程序中重用代码，而不复制相同的代码<code>.c</code>文件无处不在。这正是图书馆的用途。</p><p>库是预编译目标文件的集合（<code>.o</code>）打包在一起。主要有两种：</p><table tabindex="0"><thead><tr><th>类型</th><th>扩展</th><th>已加载</th><th>典型用途</th></tr></thead><tbody><tr><td>静态库</td><td><code>.a</code></td><td>编译时</td><td>更简单、独立的可执行文件</td></tr><tr><td>共享图书馆</td><td><code>.so</code></td><td>运行时</td><td>更小的二进制文件，可在系统范围内重复使用</td></tr></tbody></table><p>让我们看看如何构建和使用两者。</p><h4 id="步骤-1-构建静态库-a" tabindex="-1">步骤 1. 构建静态库 (.a) <a class="header-anchor" href="#步骤-1-构建静态库-a" aria-label="Permalink to &quot;步骤 1. 构建静态库 (.a)&quot;">​</a></h4><p>静态库只是目标文件的存档。</p><p>示例项目：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>math.c</span></span>
<span class="line"><span>string_utils.c</span></span>
<span class="line"><span>main.c</span></span></code></pre></div><p>数学.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>int mul(int a, int b) { return a * b; }</span></span></code></pre></div><p>string_utils.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int str_eq(const char *a, const char *b) {</span></span>
<span class="line"><span>    return strcmp(a, b) == 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>数学.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>int mul(int a, int b);</span></span></code></pre></div><p>字符串_utils.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int str_eq(const char *a, const char *b);</span></span></code></pre></div><p>编译目标文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c math.c string_utils.c</span></span></code></pre></div><p>创建静态库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ar rcs libmylib.a math.o string_utils.o</span></span></code></pre></div><p>现在你有<code>libmylib.a</code>，你的第一个静态库。</p><h4 id="步骤-2-链接库" tabindex="-1">步骤 2. 链接库 <a class="header-anchor" href="#步骤-2-链接库" aria-label="Permalink to &quot;步骤 2. 链接库&quot;">​</a></h4><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;math.h&quot;</span></span>
<span class="line"><span>#include &quot;string_utils.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;3 + 4 = %d\\n&quot;, add(3, 4));</span></span>
<span class="line"><span>    printf(&quot;Equal? %d\\n&quot;, str_eq(&quot;abc&quot;, &quot;abc&quot;));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>链接它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -L. -lmylib -o app</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>3 + 4 = 7</span></span>
<span class="line"><span>Equal? 1</span></span></code></pre></div><p>这里：</p><p>-<code>-L.</code>告诉编译器在当前目录中查找 -<code>-lmylib</code>链接反对<code>libmylib.a</code></p><p>这<code>.a</code>文件已复制到您的可执行文件中，您现在可以删除它，并且您的程序仍将运行。</p><h4 id="步骤-3-检查静态库" tabindex="-1">步骤 3. 检查静态库 <a class="header-anchor" href="#步骤-3-检查静态库" aria-label="Permalink to &quot;步骤 3. 检查静态库&quot;">​</a></h4><p>列出其内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ar -t libmylib.a</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>math.o</span></span>
<span class="line"><span>string_utils.o</span></span></code></pre></div><p>提取文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ar -x libmylib.a math.o</span></span></code></pre></div><p>你可以想到<code>.a</code>像“.zip”这样的文件<code>.o</code>模块。</p><h4 id="步骤-4-构建共享库-so" tabindex="-1">步骤 4. 构建共享库 (.so) <a class="header-anchor" href="#步骤-4-构建共享库-so" aria-label="Permalink to &quot;步骤 4. 构建共享库 (.so)&quot;">​</a></h4><p>共享库在运行时动态加载，而不是编译到可执行文件中。它们就是你所看到的<code>/usr/lib</code>作为<code>.so</code>（Linux）或<code>.dll</code>（视窗）。</p><p>构建一个：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -fPIC -c math.c string_utils.c</span></span>
<span class="line"><span>gcc -shared -o libmylib.so math.o string_utils.o</span></span></code></pre></div><p>现在你有了一个共享库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>libmylib.so</span></span></code></pre></div><p><code>-fPIC</code>表示共享库所需的“位置无关代码”。</p><h4 id="步骤-5-链接一个程序" tabindex="-1">步骤 5. 链接一个程序 <a class="header-anchor" href="#步骤-5-链接一个程序" aria-label="Permalink to &quot;步骤 5. 链接一个程序&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -L. -lmylib -o app</span></span></code></pre></div><p>运行它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./app</span></span></code></pre></div><p>如果你得到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error while loading shared libraries: libmylib.so: cannot open shared object file</span></span></code></pre></div><p>需要将当前目录添加到运行时库路径中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export LD_LIBRARY_PATH=.</span></span>
<span class="line"><span>./app</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>3 + 4 = 7</span></span>
<span class="line"><span>Equal? 1</span></span></code></pre></div><h4 id="步骤-6-验证链接类型" tabindex="-1">步骤 6. 验证链接类型 <a class="header-anchor" href="#步骤-6-验证链接类型" aria-label="Permalink to &quot;步骤 6. 验证链接类型&quot;">​</a></h4><p>检查您的程序是静态链接还是动态链接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ldd app</span></span></code></pre></div><p>动态链接的输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>libmylib.so =&gt; ./libmylib.so (0x00007f8e8b...)</span></span>
<span class="line"><span>libc.so.6 =&gt; /lib/x86_64-linux-gnu/libc.so.6 (...)</span></span></code></pre></div><p>对于静态链接，<code>libmylib.a</code>不会出现，它被烘焙到可执行文件中。</p><h4 id="步骤-7-在系统范围内安装库" tabindex="-1">步骤 7. 在系统范围内安装库 <a class="header-anchor" href="#步骤-7-在系统范围内安装库" aria-label="Permalink to &quot;步骤 7. 在系统范围内安装库&quot;">​</a></h4><p>为了使您的图书馆可以在全球范围内访问：</p><p>复制<code>.so</code>文件到<code>/usr/local/lib</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo cp libmylib.so /usr/local/lib</span></span>
<span class="line"><span>sudo ldconfig</span></span></code></pre></div><p>将标题复制到<code>/usr/local/include</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo cp math.h string_utils.h /usr/local/include</span></span></code></pre></div><p>现在您可以使用以下命令在任何地方进行编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -lmylib -o app</span></span></code></pre></div><h4 id="步骤-8-对共享库进行版本控制" tabindex="-1">步骤 8. 对共享库进行版本控制 <a class="header-anchor" href="#步骤-8-对共享库进行版本控制" aria-label="Permalink to &quot;步骤 8. 对共享库进行版本控制&quot;">​</a></h4><p>现实世界的共享库包含版本号以实现兼容性：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>libmylib.so.1.0.0</span></span>
<span class="line"><span>libmylib.so -&gt; libmylib.so.1.0.0  (symlink)</span></span></code></pre></div><p>您可以在构建期间设置它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -shared -Wl,-soname,libmylib.so.1 -o libmylib.so.1.0.0 math.o string_utils.o</span></span>
<span class="line"><span>ln -sf libmylib.so.1.0.0 libmylib.so</span></span></code></pre></div><h4 id="小代码-组合示例" tabindex="-1">小代码：组合示例 <a class="header-anchor" href="#小代码-组合示例" aria-label="Permalink to &quot;小代码：组合示例&quot;">​</a></h4><p>生成文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -fPIC</span></span>
<span class="line"><span>OBJS = math.o string_utils.o</span></span>
<span class="line"><span>TARGET_STATIC = libmylib.a</span></span>
<span class="line"><span>TARGET_SHARED = libmylib.so</span></span>
<span class="line"><span>all: $(TARGET_STATIC) $(TARGET_SHARED)</span></span>
<span class="line"><span>$(TARGET_STATIC): $(OBJS)</span></span>
<span class="line"><span>    ar rcs $@ $^</span></span>
<span class="line"><span>$(TARGET_SHARED): $(OBJS)</span></span>
<span class="line"><span>    $(CC) -shared -o $@ $^</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJS) $(TARGET_STATIC) $(TARGET_SHARED)</span></span></code></pre></div><p>建造：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span></code></pre></div><p>链接应用程序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -L. -lmylib -o app</span></span></code></pre></div><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LD_LIBRARY_PATH=. ./app</span></span></code></pre></div><h4 id="步骤-9-静态与共享权衡" tabindex="-1">步骤 9. 静态与共享权衡 <a class="header-anchor" href="#步骤-9-静态与共享权衡" aria-label="Permalink to &quot;步骤 9. 静态与共享权衡&quot;">​</a></h4><table tabindex="0"><thead><tr><th>特色</th><th>静止的 （<code>.a</code>)</th><th>共享（<code>.so</code>)</th></tr></thead><tbody><tr><td>链接</td><td>编译时</td><td>运行时</td></tr><tr><td>文件大小</td><td>更大的可执行文件</td><td>较小的可执行文件</td></tr><tr><td>更新</td><td>需要重新编译</td><td>代替<code>.so</code>文件</td></tr><tr><td>便携性</td><td>完全独立</td><td>需要图书馆存在</td></tr><tr><td>速度</td><td>稍微快一点</td><td>轻微加载延迟</td></tr></tbody></table><p>对于小型工具或嵌入式系统，请使用静态。对于大型或可更新的软件，更喜欢共享。</p><h4 id="步骤-10-检查库符号" tabindex="-1">步骤 10. 检查库符号 <a class="header-anchor" href="#步骤-10-检查库符号" aria-label="Permalink to &quot;步骤 10. 检查库符号&quot;">​</a></h4><p>要查看导出了哪些函数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nm -D libmylib.so | grep add</span></span></code></pre></div><p>要检查动态符号解析：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>objdump -T libmylib.so | head</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>库使您的 C 代码模块化、可维护且可重用。它们是每个严肃的 C 生态系统的基础，从<code>libc</code>到 OpenSSL 到 SDL。</p><p>一旦您了解如何构建和链接您自己的<code>.a</code>和<code>.so</code>文件，您可以：</p><ul><li>提供其他人可以使用的 API</li><li>干净地组织大型代码库</li><li>了解系统库如何集成到您编译的每个程序中</li></ul><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>建立一个小型数学库（<code>libmathx.a</code>,<code>libmathx.so</code>).</li><li>创建一个仅包含标头的帮助程序并在多个程序中对其进行测试。</li><li>尝试在一个构建中混合静态库和共享库。</li><li>检查您的共享库<code>ldd</code>和<code>nm</code>.</li><li>版本化你的<code>.so</code>使用符号链接的文件并测试兼容性。</li></ol><p>接下来，您将探索编译器标志和优化级别如何影响性能、安全性和调试，学习如何调整<code>gcc</code>对于开发和发布版本。</p>`,100)])])}const u=s(p,[["render",i]]);export{r as __pageData,u as default};
